INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1050107-che204', 'stk-user3786', 'CHE 204', 'info', '{"desc": "هذا الكورس عند بعض الطلاب متوسط و بعضهم صعب\nيتكلم الكورس عن fluids و تأثير الأحتكاك friction\nلتوضيح الهدف بدون تفاصيل\nلو طلب منك توصل مياه من المنطقة الشرقية للرياض فتصميم الـ pipe و صفات الـ pump راح تستخدم هذا الكورس\nالكتاب ماعندي معلومات عنه لأني درست الكورس على نوت الدكتور احمد الصالح و كان الكتاب مرجع فقط\nأخذت الكورس عند الدكتور علي الشامة و الدكتور في قمة الأخلاق إذا تروح مكتبه راح يتعب معك\nفي طلاب ينصحون بالدكتور معتز في هذا الكورس", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/che-204-transport-phenomena-i/120650/2", "user": "user3786", "ts": 1338749497000, "tid": 120650, "pn": 2}}', 1338749497000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1102736-che204', 'stk-user6441', 'CHE 204', 'info', '{"desc": "السلام عليكم\n\nالكورس مهم جدا بل يعتبر من اهم الكورسات في الكيميكال\n\nباختصار الكورس يتكلم عن كل شي ممكن يأثر على الفلويد داخل البايب وتحويلها الى معادلات رياضيه\n\nالاشياء اللي ممكن تأثر على الفلويد وراح يغطيها المنهج مثل :\nااحتكاك بين الفلويد والبايب\nتغير مستوى ارتفاع البايب\nخصائص الفلويد نفسه من دينسيتي الى فيسكوسيتي الى ديفيوجن …etc مع تغير درحة الحراره والضغط\nفرق البرشر في السيستم\nالمومنتوم الناتج عن سرعة الفلويد\nشكل الـflowing film اذا Turbulent او laminar\nاذا فيه pump في السيستم\nاذا في particles داخل البايب\nاذا في valves\nاذا فيه rings\n\n…\n\nالكتاب المستخدم للمقرر\n\nالكتاب مو بذاك السوء بس مشكلته مليان دريفيشن ما حنا بحاجتها\nالامثله الي فيه جيده وواضحه\nانصح بالمذاكر من النوت وبعدين حل الامثله الي في الكتاب\n\nهذا الملف فيه سلايدات علي الشامي و شوية حاجات ممكن تفيدكم\nhttp://www.4shared.com/rar/MH-aPmG5/che204Pepsi.html\n^^\nاخلي ذمتي ممن قد يستخدمه في الغش\n\nبالتوفيق 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/che-204-transport-phenomena-i/120650/3", "user": "user6441", "ts": 1349302186000, "tid": 120650, "pn": 3}}', 1349302186000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1199237-che204', 'stk-chemist', 'CHE 204', 'info', '{"desc": "جودة المقرر بشكل عام:\nمهم جدا للمهندس الكيميائي بل هو فرع أساسي في القسم\n\nالمواضيع التي يغطيها المقرر:\n1) دراسة خواص الموائع\n2) Types of the Flows laminar or turblent\n3) الضغط في الموائع وانواع الأنابيب الناقله\n4) تصميم الانابيب على حسب خصائص المائع\nوغيره\n\nالكتاب المستخدم للمقرر:\nاسؤ كتاب مر على في الجامعة 😞 من كل النواحي اخراج, عرض المادة, الأمثلة المحلولة, التمارين. سئ بما تعنيه الكلمة من معنى ولكن الحمد لله يقولون انه تغير للأفضل.\n\nمدى فائدته في الناحية التطبيقية:\nمهم جدا في التصميم في حياتك الوظيفيه إن شاء الله", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/che-204-transport-phenomena-i/120650/4", "user": "Chemist", "ts": 1363223058000, "tid": 120650, "pn": 4}}', 1363223058000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1233651-che204', 'stk-cesar_peace', 'CHE 204', 'info', '{"desc": "+1\n\nسر التفوّق في هذي المادة … المتابعة المستمرة و حل الهوموركات بنفسك\n\nانصح بالمذاكرة من نوتات الدكتور اسامة المبيض : من هنا , تكفي بإذن الله مع شرح الدكتور\n\nالمادة ممتعة جدا … حاول بس تعطيها شوية اهتمام وبتضبط امورك فيها … ولاتسمع كلام اللي يقولك انها غثيثة ومدري ايش ! … إذا قدرت تنزلها مع الدكتور زهير مليباري اختصرت نص الطريق الى الـ A+ 😁", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/che-204-transport-phenomena-i/120650/7", "user": "CeSaR_PeaCe", "ts": 1370829218000, "tid": 120650, "pn": 7}}', 1370829218000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1251057-che204', 'stk-user4492', 'CHE 204', 'info', '{"desc": "أكثر الطلاب خوفونا من مادتين 204 والأورقانك ،\nولكن الـ 204 حلها بسيط وهي حل الواجبات بنفسك، وراجعها قبل الميجر ،\nنفس الأفكار وماراح يطلعون عنها ،\n\nأفضل مذاكرة الصراحة من نوتات المبيض ،\nالكتاب يضيع شوي ، بس حل الأمثلة اللي فيه ❤️\n\nماعليكم من الكلام اللي تسمعونه عنها،\nسووا اللي عليكم وفالكم a+", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/che-204-transport-phenomena-i/120650/8", "user": "user4492", "ts": 1375446298000, "tid": 120650, "pn": 8}}', 1375446298000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1258639-che204', 'stk-user6918', 'CHE 204', 'info', '{"desc": "مادة ممتعة وتحس صراحة انها من اهم المواد الي تفيدك في تخصصك\nبس يبيلها طولت بال في البداية راح تكون مضيع بس كل ما تستمر قدام توضح الفكرة اكثر\nصراحة انا نزلتها صيفي وكانت زي الحلاوة مع الدكتور شيخ عبدالرزاق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/che-204-transport-phenomena-i/120650/9", "user": "user6918", "ts": 1378137218000, "tid": 120650, "pn": 9}}', 1378137218000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1373953-che204', 'stk-guest', 'CHE 204', 'info', '{"desc": "أخذت المادة في سمستر 132 مع الدكتور شيخ عبدالرزاق، طبعا سمعة المادة سيئة جدا و السبب الرئيسي هو الكتاب السقيم ، الكتاب عبارة عن مجموعة من الاشتقاقات الطويلة التي لا يحتاجها طالب البكاليريوس نهائيا كتاب سيء جدا و القسم من حوالي ثلاث سنوات يدعي بأنه سيغيره لكنهم ما غيروا شي ، في بعض الجزئيات اضطريت أني أرجع للكتاب اللي يدرسوه طلاب الميكانيكل في me 311 عشان أقدر أفهم، المادة كمفهوم بسيطة لكن ما عندك أي مصدر جيد للمذاكرة حتى نوت المبيض مو مرة ممتاز لكنه يعطيك الزبدة لحل الأسئلة ، اذا تغبى تجيب قريد جيد لازم تحاول تفهم الكونسبت صح و تعرف كيف تطبق القوانين و تجمع درجات قد ما تقدر لأنه ممكن يجيك سؤال في الميجر عليه 25% و ما تعرف فكرته فتاخذ صفر ببساطة ، في نهاية الكورس في تشابتر مدري ايش فايدته كله ماث 201 و ماث 202 كيف تشتق معادلات للسرعة و العزم و هذا الكلام لا تخافوا من هذا التشابتر لأنهم بيجيبوا سؤال زي الهوموورك عليه، موفقين\n\nرسالة للقسم : استمرار تدريس هذا الكتاب شيء مخجل", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/che-204-transport-phenomena-i/120650/11", "user": "Guest", "ts": 1401370682000, "tid": 120650, "pn": 11}}', 1401370682000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1453702-che204', 'stk-user9534', 'CHE 204', 'info', '{"desc": "كنت أسمع بأن هذا الكورس صعب أيام الكتاب الأصفر القديم المخيس XD\nالحين جابوا كتاب جديد ومررررررررررة ممتاز من ناحية الأمثلة والأسئلة نهاية كل شابتر\n\nأفضل طريقة لمذاكرة هذه المادة : حل الواجب وفهمه بشكل كامل , حل أمثلة الكتاب . أسئلة المياجر والفاينل كانت نفس أفكار الواجب والأمثلة مع تريكات خفيفة\n\nهذا رابط فيه مانيوال سلوشن للكتاب (تلقاه بالأخير من التولز)+ هاند اوتس حل أمثلة الكتاب بطريقة الدكتور أسامة المبيض\n\nche 204 Hand outs& solution manual", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/che-204-transport-phenomena-i/120650/17", "user": "user9534", "ts": 1468382170000, "tid": 120650, "pn": 17}}', 1468382170000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1527399-che204', 'stk-user11325', 'CHE 204', 'info', '{"desc": "che204-201\nالكورس حليو مب صعب بس طويل شوي وعلى حظنا بذا الترم خلوا الفاينل 4 فصول عموما الكورس يتكلم عن حركة السوائل والغازات داخل الانابيب وخارجها وعن خواص هذه السوائل من حساب للزوجة وما الى ذلك وبتدرس انواع ال flow والعوامل اللي تاثر فيه داخل البايب ومعادلة بيونولي يعتبر اساس الكورس ذا\n\nالكتاب ممتاز ويكفي للمذاكرة وغالبا الدكاترة يحطون الاختبارات نفس افكار الواجبات الللي يعطونها لطلابهم. عموما افضل طريقة للمذاكرة من وجهة نظري تحل الامثلة ثم تحل الواجبات او sugessted problems وثم تحل كم سؤال من اخر الشابتر. ودعواتكم لي يا اخوان", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/che-204-transport-phenomena-i/120650/22", "user": "user11325", "ts": 1609346331000, "tid": 120650, "pn": 22}}', 1609346331000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1527463-che204', 'stk-aomab', 'CHE 204', 'info', '{"desc": "جودة المقرر بشكل عام\n\nالمادة جميلة وممتعة\n\nالمواضيع التي يغطيها المقرر\n\nالمنهج مقسم لعدة اقسام + Packed bed من خارج الكتاب\n\nالفصول 1 2 3\n\nتعتمد مقدمة بسيطة راح تراجع اشياء اخذتها من الفيزياء + كم شيء بسيط\nراح تدرس الوحدات واللزوجة والضغط\n\nالفصل 5\n\nراح تدرس Bernoulli Equation وتطبيقاتها + Efficiency\n\nالفصل 6\n\nراح تدرس Momentum Balance Equation وهو عبارة عن قسم بسيط\n\nالفصل 7 يعتبر الاسهل\n\nDimensional Analysis\n\nالفصل 8\n\nراح تتعلم كيف تطلع hl الموجودة في Bernoulli Equation\nاللي درستها في الفصل 5\n\nPacked bed\n\nموضوع سهل وبسيط مجرد تعوض في القوانين وامورك تمام\n\nالفصل 9\n\nراح تتعلم فيه الاشتقاق وتتفاوت الاسئلة فيه بين السهل جدا والصعب\n\nالفصل 11\n\nما كان ضمن الفاينل فما اقدر افيدك فيه 😁\n\nالكتاب المستخدم للمقرر\nالكتاب لا بأس به اسئلته كويسه ويجي منها في الاختبارات\nhttps://images-se-ed.com/ws/Storage/Originals/978125/901/9781259011221L.jpg?h=189fe0178330575286d22e255c0a4ac7\n\nالأسئلة والأمثلة المستخدمة في المقرر\nاسئلة الكتاب + اسئلة الواجب\n\nمدى فائدته في الناحية التطبيقية\nمهم ومفيد جدا زي اي مادة تخصص\n\nاضافات :\n\nهناك ملف مضغوط تم رفعه في kfupm resources قسم Notes & Slides يحتوي على اسئلة الترم 192 و201 مع ملفات مفيدة\n\nوفالكم A+", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/che-204-transport-phenomena-i/120650/23", "user": "AOMAB", "ts": 1609520087000, "tid": 120650, "pn": 23}}', 1609520087000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mjehad-che204', 'stk-mjehad', 'CHE 204', 'doc', '{"docs": [{"id": "stk-dr-f98545", "n": "Dr. Osamah Al-Mubaiyedh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHE 204 - Term 122\n\nالتحضير : يوميا وشدييد واوقات ما يسمح للمتأخر بالدخوول\n\nطريقة الشرح : شرحه حلو وكويس عنده ملفات pdf هو مسويها ممتازة يشرح عليها وبعض الكلاسات يكتب نوت\n\nالكويزات : متوسطة مائلة للصعوبة ويقولك استخدم اي شي حتى الجوال وجيب اي سورس معاك ماعندي مشكلة\n\nالمياجر: كومن\n\nالفاينلات : كومن\n\nالقريد النهائي: B+\n\nالصوت: واضح\n\nإضافات : مشكلة هالدكتور اخلاقه سيئة مع الطلاب ويهزأ ويحطم الطلاب اللي مياجرهم نازلة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1393537-che204", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/osamah-al-mubaiyedh/98545/7", "user": "mjehad", "ts": 1409120868000, "tid": 98545, "pn": 7}}]}', 1409120868000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-gamofrn-che204', 'stk-gamofrn', 'CHE 204', 'doc', '{"docs": [{"id": "stk-dr-f98545", "n": "Dr. Osamah Al-Mubaiyedh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHE 204 - Term 142\n\nالتحضير :ناسي بالظبط … بس الأكيد انه كان يحضر … ولا يحب احد يتأخر المحاضرة\nطريقة الشرح :شرحه نووعا ما فوق المتوسط … والي مخليه به>ا المستوى انه من زمان يدرس هالكورس على ماعتقد\nومايدخل بالتفاصيل … وهالشى احس مب بمصلحة الطالب … لأن في اشياء تحتاج تفاصيل\nالكويزات :الكوزات … برضو نسيت … بس على ماعتقد اختبرنا 4 كوزات او 5 … وكان مستوى الأسئلة متوسط …\nالمياجر:كومن …\nالفاينلات :كومن…\nالقريد النهائي:B\nالصوت:excellent\nإضافات :الدككتور اخلاقه لك عليها … والهاند اوت الي يوزعها حلوة … وتصحيحه تقريبا حلو …\nالدكتور اسامة هو الأفضل بتدريس هالكورس … مقارنة مع عبد الرزاق و السوداني …\n\n*الدكتور يعطي واجبات بتنظام … والميياجر والفاينلات اوبن بوك … فا نصيحة لك\nلا تفكر ابدا ابدا تنقل الواجب … لو كان >لك راح يسبب لك التعب والسهر …(حاول تفهم) …\nلكن صدقني بتجيب درجات حلوة بالأختبارات …\n\n*ببداية الككورس بتحس نفسك ضايع … صدقني اسمع كلام الدكتور بالظبط … وحل كل شى يقولك عليه\nوسجل كل شى يقول عنه مهم … او تحس انه كأنه في تلميح للأختبارات\n\nتحية خاصة للدكتور اسامة … كان دائما يقول اوعدكم ان ماراح تطلع من الكورس الا وانت مستفييييييد 🙂", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1433165-che204", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/osamah-al-mubaiyedh/98545/9", "user": "GAMOFRN", "ts": 1447404710000, "tid": 98545, "pn": 9}}]}', 1447404710000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ali-che-che204', 'stk-ali-che', 'CHE 204', 'doc', '{"docs": [{"id": "stk-dr-f98545", "n": "Dr. Osamah Al-Mubaiyedh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Che204\nالتحضير :\nتمر ورقه على الطلاب بدايه الكلاس\nطريقة الشرح :\nيستخدم سلايدات مرتبه في الشرح وواضحه ومختصره\nيحل الامثله بخط يده ويرفعهم في ملفات pdf ويشرح منهم\nامثله كثيره ومنوعه\nالكويزات :\nمتوسطه الى متوسطه الصعوبه\nاذا تحل الهومورك راح يكفي تجيب درجات كويسه\nالمياجر:\nكومن و تصحيح الدكتور ممتاز تحصل حقك واعلى\nالفاينلات :\nكومن\nالقريد النهائي:\nA\nالصوت:جدا واضح ولغة االدكتور ممتازة\nإضافات :\nلا تستخدم الجوال اثناء الشرح ولا تفكر تحضر زميلك بالورقه\nالدكتور خلوق وحبوب وجدا فاهم بالكورس\nلا تفوته", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1438455-che204", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/osamah-al-mubaiyedh/98545/12", "user": "Ali-CHE", "ts": 1452428492000, "tid": 98545, "pn": 12}}]}', 1452428492000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user9306-che204', 'stk-user9306', 'CHE 204', 'doc', '{"docs": [{"id": "stk-dr-f98545", "n": "Dr. Osamah Al-Mubaiyedh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "انا الحين عنده في مادةCHE-204 استاذ رائع بمعنى الكلمة لكن الاخلاق لك عليها شوي, لكن اللي يهمنا اكثر هو الشرح والقريدات وهو بطل فيها صراحة وبختصار سو اللي يقولك عليه وراح تجيب درجات حلوة لان هو من كثر مادرس الطلاب صارت عنده خبرة في احتياجاتهم لذلك انا اعطيه a+ a+ a+a+a+a+a+a+a+a+a+a+a+a+a+a+a+a+a+ a+ a+ a+a+a+a+a+a+a+a+a+a+a+a+a+a+a+a+a+ a+ a+ a+a+a+a+a+a+a+a+a+a+a+a+a+a+a+a+a+ a+ a+ a+a+a+a+a+a+a+a+a+a+a+a+a+a+a+a+a+ a+ a+ a+a+a+a+a+a+a+a+a+a+a+a+a+a+a+a+a+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1445497-che204", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/osamah-al-mubaiyedh/98545/13", "user": "user9306", "ts": 1459507515000, "tid": 98545, "pn": 13}}]}', 1459507515000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mahmo0od-che204', 'stk-mahmo0od', 'CHE 204', 'doc', '{"docs": [{"id": "stk-dr-f98551", "n": "Dr. Nadhir Al-Baghli", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ترم 172 درست ، مادة CHE 204\n\nالي يدرس هالمادة كان دكتورين الجهني و البغلي\n\nانا كنت احد طلاب الجهني ، طبعاً اسئلة المياجر كانت تصحح بالتناصف بينهم.\n\nالاسئلة الي تصحح عن البغلي كانت دائماً الدرجات فيها مررررررة سيئة للاسسف و على اشياء والله العظيم تافه وانا محاسب على كلامي ، تعزيزاً على كلام اخوي صالح كان فعلاً عصبي جداً فالمكتب وما يبي احد يناقشه و يبيك تمشي بالضبط على السلوشن الي عنده غير كذا م ينفع و يبيك توضح كل شي كل شي ، اما سالفة هالشي مفهوم او واضح م يمشي معاه.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1492756-che204", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/nadhir-al-baghli/98551/20", "user": "mahmo0od", "ts": 1526777604000, "tid": 98551, "pn": 20}}]}', 1526777604000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-aomab-che204', 'stk-aomab', 'CHE 204', 'doc', '{"docs": [{"id": "stk-dr-f99335", "n": "Dr. A Al-Shammari", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHE 204 - Term 201\n\nالتحضير :\n\nجدا متعاون يسمح بالتأخير يمشي لك كم غياب\n\nطريقة الشرح :\n\nالشرح ما اقدر اقيمة لان الترم عن بعد لكن بشكل عام\nجيد و يسمح بالاسئلة\n\nالكويزات :\n\nسهلة جدا غالبا تكون من اسئلة الكتاب\n\nتصحيحه جدا منصف يعطيك زيادة عن حقك احيانا\n\nالمياجر:\nكومن\nالفاينلات :\nكومن\nالقريد النهائي: A+\nالصوت:\n\nواضح جدا\n\nإضافات :\n\nالدكتور ما شاء الله يعتبر الأكثر تعاونا مع الطلاب ويهتم لمصلحتهم\nاذا لقيته في مادة لا يفوتك\n\nوبالتوفيق", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527556-che204", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-al-shammari/99335/22", "user": "AOMAB", "ts": 1609776405000, "tid": 99335, "pn": 22}}]}', 1609776405000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-kirsty13-che204', 'stk-kirsty13', 'CHE 204', 'doc', '{"docs": [{"id": "stk-dr-f99335", "n": "Dr. A Al-Shammari", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHE 204 - Term 211\n\nالتحضير :\n\nجدا متعاون يسمح بالتأخير يقبل ميك اب بدون ما تكلمه\n\nطريقة الشرح :\n\nيعرض نوتات على البروجكتر ويعلق ويفصل على السبورة ، جدا متمكن من ايصال المعلومات ويبسطها لك بطريقة حلوة ومختصرة . وقت حل المسائل اجمل مافيه انه يفصل فيها ولا يفترض انك فيه شي فاهمه من قبل ، يقبل الاسئلة بصدر رحب جدا ولا يزعل ويحب الطلاب المتفاعلين معه. الدكتور أعسر فلو تقدر تجلس على اليسار احسن لك .\n\nالكويزات :\n\nسهلة جدا تكون من اسئلة الكتاب\n\nتصحيحه جدا منصف يعطيك زيادة عن حقك، تبين له انك فاهم وتكون غلطان بحسابات يعطيك درجة مرة حلوة .\n\nالمياجر:\nميجر ١ سهل 18.1/ 25 AVG\nميجر ٢ متوسط مائل للسهولة\nAVG 17/25\nالفاينل :\nكان سهل AVG 21.5/30\nالقريد النهائي: A+\nالصوت:\nواضح جدا جهوري ومسموع ماشاء الله\n\nإضافات : الدكتور عسل بمعنى الكلمة كامل والكامل الله ، دايم مبتسم ويضحك معنا ولا عمره دخل الكلاس وهو مكشر الله يسعده، ينكت ويمزح مع الطلاب ولا عمره غلط على احد . برضوا الدكتور ما عنده نظام الخير يخص والشر يعم ، نظامه يحاسب المخطئين فقط وتراه يسامح ويمشي كثير لكن يكره الاستغفال . افرج الكورس كان 77 وحطه B وكل خمس درجات قريد ، اذا باقي لك فواصل على القريد اللي بعده يعطيك . وأخيرا وليس اخرا الدكتور رجال وقد كلامه ، اذا قالك ذاكر هذا الشي ويكفيك او هذا محذوف او ما بيطلع الاختبار من هنا فهو قول وفعل مو مثل بعض دكاترة القسم هداهم الله . لو ينزل اي كورس قدام بنزل عنده وانا مغمض الله يوفقه وين ما كان.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533258-che204", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-al-shammari/99335/23", "user": "Kirsty13", "ts": 1641179894000, "tid": 99335, "pn": 23}}]}', 1641179894000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ahmed1-che204', 'stk-ahmed1', 'CHE 204', 'doc', '{"docs": [{"id": "stk-dr-f99335", "n": "Dr. A Al-Shammari", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHE 204 - Term 212\n\nالتحضير : بعد بداية الكلاس بكم دقيقة ويحضرك اذا جيت متأخر بس كلمه بعد الكلاس، التحضير عنده مب يوميا بعد.\n\nطريقة الشرح : يوضح الكونسبت ويحاول يجيب امثلة في الواقع تقرب لك المفهوم وبعدين يشرح المسائل و انواعها، لاحظ قلت يشرح لانه ما يحلهم يعلمك شلون تحل والتعويض عليك انت، شرحه ما حسيته ذاك الاسطوري بس يعتبر كويس.\n\nالكويزات : اختبرنا 6 كويزات كلهم سهلين وطبعا اخذ افضل 5 والسادس اوبشنال.\n\nالمياجر: كومن\nالفاينلات : كومن\n\nالقريد النهائي: A\n\nالصوت: يعني لو تجلس ورا و الكلاس كان كبير ما راح تسمع كل كلامه، تقدر تقول ضعيف.\n\nإضافات : حاول تجلس يسار لانه الدكتور بيعطيك ظهره اذا كنت يمين وما بتشوف زي الناس، الدكتور اخلاقه حلوة ومسهل المادة.\n\nانصح فيه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1534440-che204", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-al-shammari/99335/24", "user": "Ahmed1", "ts": 1653468779000, "tid": 99335, "pn": 24}}]}', 1653468779000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-saleh_h-che204', 'stk-saleh_h', 'CHE 204', 'doc', '{"docs": [{"id": "stk-dr-f99335", "n": "Dr. A Al-Shammari", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHE 204 - Term 212\n\nالتحضير : يحضر كل محاضرة ويمشي التأخير ومتعاون\nطريقة الشرح : يشرح من نوتاته ببرنامج One Note وسلايداته ممتازة والشرح ممتاز جدًا\nالكويزات : سهلة إلى متوسطة، تجي نفس افكار الواجب وغالبًا تكون من الكتاب.\nالمياجر: المادة فيها ميد تيرم كومن وكان سهل صراحة\nالفاينلات : كومن وكان الفاينل حراق حبتين\nالقريد النهائي: A\nالصوت: ضعيف نوعًا ما ف يبيلك تقعد قدام عشان تسمعه زين\nإضافات : الدكتور محترم جدا ومتعاون فيما يخص التحضير والغياب وتصحيحه ممتاز جدًا يدف دف محترم بالبارشيال … عمومًا اشوفه الخيار الاول لك اذا بتسجل الكورس لانه افضل الموجودين.\nوموفقين ان شاء الله.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1534504-che204", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-al-shammari/99335/25", "user": "Saleh_H", "ts": 1653848317000, "tid": 99335, "pn": 25}}]}', 1653848317000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-forlan-che204', 'stk-forlan', 'CHE 204', 'doc', '{"docs": [{"id": "stk-dr-f115322", "n": "Dr. Z Malibari", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "السلام عليكم\nطريقة الشرح : اخذت عند الدكتور che204 …الدكتور سعودي وعلى ما اظن انه اخذ البكالريوس من البترول …\nا يكتب على السبورة بخط واااضح وبشكل مرتب يعني يمديك تكتب معاه نوت …بس للاسف الكورس كله دريفيشن عشان كذا بتتعب …بس للامانة الرجال شرررريح ويشرح من قلب و انا من الاشخاص الي ارتحت لشرحة …وبرضة فاهم في التقنية يعني كان يستخدم طرق عدة يستخدم اسلايدات احيانا وكان يستخدم حتى اليوتيوب\nشديد جدا بالتحضير : بعد 10 لا تدخل ( بس مافيه تاخير ) وهالنقطة مشدد فيها\n\nالكويزات : اخذنا 6 كوزات اول ثلاثة كان ناااار وجبنا فيها 0 و 2 و3 ^___^ بس رجع سهلها لنا بالاخير وبشكل عام اسالته قريبة من الهومورك او حتى نفسها بس الكورس ما يستحمل 🙂\n\nالمياجر: تصحيحة عادل بالتصحيح يعني نفس بقية الدكاترة بس الي يفرق انه ممكن يعطي بارتشل كريديتز لو تاكد انك فاهم شوي ن الفكرة\n\nالفاينلات : كومون ( وكان نص نص في الصعوبة )\nالقريد النهائي: A ___( اعطيته بناء على شرحة وبرضة لانه وفى بوعدة )\n\nالصوت: حلو يعني مسموع ويخليك تصحصح\n\nإضافات : الدكتور خلوق ولاحظت عليه ان ماعمرة دخل كلاس وما كتب بسم الله الرحمن الرحيم وهالنقطة عجبتني فيه اضف على ذلك يعطي بارتيشل خذ مثلا وعدنا الي مايغيب يعطية 2% اضافة ووفا بوعدة … وكنا مخبصين بالميجر عطانا كويز زيادة اضافي على كل الدرجات … 🌹…الدكتور حقاني بمعنى الكلمة سهل تاخذ معه قريد وسهل تاخذ معه F يعني حقك بتاخذة وبينزل كل شي موضح بالنهاية … اتمنى اكون افدتكم\n__________________", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p971804-che204", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/z-malibari/115322/6", "user": "forlan", "ts": 1327174718000, "tid": 115322, "pn": 6}}]}', 1327174718000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user4988-che204', 'stk-user4988', 'CHE 204', 'doc', '{"docs": [{"id": "stk-dr-f115322", "n": "Dr. Z Malibari", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Che 204\nترم 111\n\nالتحضير : ينادي بالأسماء أو يمرر بالورقة ، شديد في موضوع التحضير و يكره حكاية إنك تحضر خويك ، كان مسوي عرض خاص للي ما يغيب البتة ( لا تغيب أبداً و راح أعطيك 2% بونص للكلاس وورك ، يعني راح تأخذ 4 من 2 في درجة الحضور ) لكن في نفس الوقت ما راح يتردد يعطي دي إن للي يتعدى الحد المسموح به في الغياب ( أتذكر إنه أعطى DN لطالبين غياباتهم كانت كثيرة )\n\nطريقة الشرح : يشرح من البلاك بورد ، أكتب وراه و سجل أي ملاحظة يقولها و راح تحصل على نوت يغنيك عن الكتاب\n\nالكويزات : كانت بدايته متوحشة ، بعد كذا لما شاف الشعب جايب العيد بدأ خفف علينا صعوبة الكويزات\n\nالمياجر: كومون\n\nالفاينلات : برضه كومون ( اللي يعين اللي كان عندهم فاينلي 203 + 204 بينهم فرق 12 ساعة قفط)\n\nالقريد النهائي: أنا أعطيه A\n\nالصوت: واضح جداً\n\nإضافات :\n\nالدكتور خلوق ولاحظت عليه ان ماعمرة دخل كلاس وما كتب بسم الله الرحمن الرحيم وهالنقطة عجبتني فيه اضف على ذلك يعطي بارتيشل خذ مثلا وعدنا الي مايغيب يعطية 2% اضافة ووفا بوعدة … وكنا مخبصين بالميجر عطانا كويز زيادة اضافي على كل الدرجات …الدكتور حقاني بمعنى الكلمة سهل تاخذ معه قريد وسهل تاخذ معه F يعني حقك بتاخذة وبينزل كل شي موضح بالنهاية\n\n+1000000\nبدايته كانت مرعبة صراحة ، لمن فعلاً لا تحكم على أحد من البداية\nالدكتور شرحه جبار و بتخرج معاه بقريد إذا كنت مهتم\nاللي عجبني فيه إنه حقاني وواضح ، مو مثل أغلب الدكاترة يعطوك القريد و هم حتى ما أعطاوك نتائج الفاينل\n\nكنت والله أتمنى إني أنزل عنده che 325 لكن للأسف الظاهر ما لنا نصيب\n\nأنصح به و بقوة للـ che204\n\nجزاكم الله خير يا دكتور زهير و يا دكتور علي الشامي ، كان كورس ممتع معكم 🤴", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1021616-che204", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/z-malibari/115322/9", "user": "user4988", "ts": 1334313993000, "tid": 115322, "pn": 9}}]}', 1334313993000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-diego_milito-che204', 'stk-diego_milito', 'CHE 204', 'doc', '{"docs": [{"id": "stk-dr-f115322", "n": "Dr. Z Malibari", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بنود التقييم :\n\nالتحضير : ينادي بالأسماء بشكل شبه يومي\nطريقة الشرح : يكتب عالسبورة كثيراً من الأحيان و اذا الموضوع طويل يستخدم السليدات و شرحه واضح و نوته كذلك واضح و يهتم لأسئلة الطلاب اذا ما كانت ساذجة.\nالكويزات : بين المتوسطة و الصعبة لأن المادة che204صعبة نوعاً ما و تحتاج الى تركيز\nالمياجر: كومون\nالفاينلات : كومون\nالقريد النهائي: A +\nالصوت: و اضح\nإضافات : المدرس خلووق نوعاً ما اول السمستر حسيته عصبي لكن في نهايته الرجال رايق و ينكت احياناً و لا يحب احد يتكلم عندما يبدأ يشرح", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1043579-che204", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/z-malibari/115322/10", "user": "Diego_Milito", "ts": 1337856394000, "tid": 115322, "pn": 10}}]}', 1337856394000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-kfupm_knight1-che204', 'stk-kfupm_knight1', 'CHE 204', 'doc', '{"docs": [{"id": "stk-dr-f115329", "n": "Dr. Ali Alshami", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أنا لسه قاعد آخذ معاه che 204 الترم هذا 111\n\nالتحضير : بشكل يومي تقريبا.\n\nطريقة الشرح: يشرح من نوتات عنده. بس عشان تفهم النوتات لازم تحضر الكلاس لأنه النوتات ملخص للكتاب ومعروف عن الكتاب انه مهو مرة سهل عشان تفهم منه. وعن نفسي أشوف شرحه جدا ممتاز وأستغرب من الناس اللي تقول انه che 204 مرة صعبة!\n\nالكويزات: متوسطة, بعض الأحيان تكون مفاجئة وبعض الأحيان يقلك متى.\n\nالمياجر والفاينالات كومن\n\nالقريد النهائي: إلى الآن أعطيه a\n\nإضافات:\nالمادة مادة كونسبت. اذا فهمته حتفهم الباقي. عشان كذا تلاقي المدرس يشرح مثال واحد في حصة كاملة. وبعض الأحيان يخلي نص الحصة لأسئلة الطلاب. والمدرس ترى جدا حبيب ومتواضع. وحلو انه يجبلك امثلة من الحياة العملية في المصنع.\nفنصيحة مني, اذا كنت تقدر المدرس اللي يفهّمك ويريّحك من المذاكرة العويصة فخذ معاه 🙂", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p936702-che204", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ali-alshami/115329/4", "user": "KFUPM_KNIGHT1", "ts": 1322186050000, "tid": 115329, "pn": 4}}]}', 1322186050000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user6661-che204', 'stk-user6661', 'CHE 204', 'doc', '{"docs": [{"id": "stk-dr-f115329", "n": "Dr. Ali Alshami", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Che 204 - ترم 111\n\nفي التحضير يحضر غالبا … واحيانا قليلة ما يحضر …\n\nالشرح يركز كثير عالكونسبت … وكتاب هالمادة معقد فهو مسهلها علينا واعطانا نوت نذاكر منها …\n\nوفي الحقيقه نوته كافي وشامل …\n\nفي ترم 111 كان هو الكواردنيتور وكان يحاول يسهل المادة عالطلاب قدر الإمكان وما قصر معنا ابدا ❤️ …\n\nمتعاون مع الطالب وبشوش دائما …\n\nتصحيحه يعطيك حقك وبس !\n\nما اظن فيه احد احسن منه في كورس الـ (204)…\n\nفيه نقطة سلبية وهو انه غير ملتزم في انهاء المحاضرة بالوقت المحدد …\n\nكلاسنا كان الساعه (11) يبدا ولازم ياخذ 5 دقايق الى 10 دقايق من بريك الغدا 😦 …\n\nاعطيه b …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p971373-che204", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ali-alshami/115329/5", "user": "user6661", "ts": 1327102956000, "tid": 115329, "pn": 5}}]}', 1327102956000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-k_94-che204', 'stk-k_94', 'CHE 204', 'doc', '{"docs": [{"id": "stk-dr-f115330", "n": "Dr. Shaikh Abdurrazzak", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "TERM 151 < CHE 204\n\nالتحضير : ينادي بالاسماء وما يقول شي لو متاخر\nطريقة الشرح : سلايدات والحل عالسبورة , شرحه مقبول والاكسنت بنقالي 😆\nالكويزات : كانت كومون بينه وبين المبيض\nالمياجر: كومون وكانت سهله\nالفاينلات : كومون وجا اصعب من مستوى المياجر\nالصوت: جدي ولكن الاكسنت صعب شوي تفهمه\nإضافات : الدكتور تصحيحه ممتاز واخلاقه رائعة , يزعل اذا استخدمت الجوال ولكن نادر يكلمك ( الا اذا الكلاس كله يستخدمه يفصل الدكتور )\n\nاعتقد افرج القريدات كان C+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1449991-che204", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/shaikh-abdurrazzak/115330/12", "user": "K_94", "ts": 1463912067000, "tid": 115330, "pn": 12}}]}', 1463912067000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ali_alhassan-che204', 'stk-ali_alhassan', 'CHE 204', 'doc', '{"docs": [{"id": "stk-dr-f115330", "n": "Dr. Shaikh Abdurrazzak", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "TERM 192\nCHE 204\n\nالدكتور حبيب و بداية السمستر قال راح يحضر بداية الكلاس بس لكن بعد ثاني اسبوع صار يحضر المتأخرين مرة ثانية بعد الشرح.\nبالنبسه لي شرحه ممتاز جدا طبعا الأكسنت حاله حال اي دكتور هندي.\nتصحيحه شديد جددا يعني عادي تغلط في سالب في الاجابه النهائيه تروح عليك اكثر من ثلاث ارباع السؤال و تبريره هو انك مهندس كيميائي و انت الي تصمم السيستم اذا الكالكوليشن حقتك غلط ف السيستم بيكون كله غلط.\nالكويزات حرفيا مثل فكرة الهوم وورك و بعض الاحيان نسخ لصق من الهوم وورك ولذلك تقريبا بتكون ضامن الكلاس وورك", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1521964-che204", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/shaikh-abdurrazzak/115330/16", "user": "Ali_Alhassan", "ts": 1589171466000, "tid": 115330, "pn": 16}}]}', 1589171466000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ahmad_che-che204', 'stk-ahmad_che', 'CHE 204', 'doc', '{"docs": [{"id": "stk-dr-f153220", "n": "Dr. Isam Al-Jundi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHE204, CHE303, CHE425, CHE495\nالتحضير : بداية الكلاس وفي كورس 303 ماكان يحضر ويعرف ان الطلاب يغيبون\nطريقة الشرح :الدكتور افضل شخص يشرح صراحة اسطوري بالشرح لابعد حد وهو افضل دكتور درسني خصوصا ب303 يشرح بكل شي ويستخدم السبورة كثير وب 425 كان معتمد على السلايدات . الدكتور يحب اللي يشارك واحيانا يعطينا تمارين نحلها بالكلاس ومتساعد من ناحية التاجيلات. كان يعطينا بوب كويزز واذا شاف ماحنا فاهمين يكنسلهز عيبه الوحيد يتاخر بالتصحيح لكن انسى انه يظلمك وتصحيحه ممتاز جدا يعني لو اخطيت بسوال بالبداية وكملت صح يعطيك حقك كامل وينقصك بس على خطاك. مثلا مره في سوال عليه 25 اخطيت باول فقره والباقي كله معتمد عليه عطاني 22 من 25. ومعايير التصحيح واضحة جدا لكل الطلاب ويعطيك فرصة تراجع معه.\nالكويزات :متوسطة\nالمياجر:متوسطة\nالفاينلات :متوسط وكل شي عنده بالافرج\nالقريد النهائي:ِ+A\nالصوت:واضح\nإضافات : الدكتور قمة بالاخلاق وحبيب ودايم مبتسم لكن يكره اللي يتكلمون بالكلاس واحذر تتطلع ججوالك.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1522341-che204", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/isam-al-jundi/153220/16", "user": "ahmad_CHE", "ts": 1590362497000, "tid": 153220, "pn": 16}}]}', 1590362497000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdullah7-che204', 'stk-abdullah7', 'CHE 204', 'doc', '{"docs": [{"id": "stk-dr-f157157", "n": "Dr. Abdul-Majeed Azad", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "132 - che204\nاول ترم له في الجامعة جاي من امريكا\nانسان طييييب جدا و متساهل في التاخير في الحضور و الهوموركات\nيشرح علي سلايدات ملخبطة نصها مكتوب بخط يدو\nاكسنت واضح\nاعطانا 3 او 4 كويزات صح و خطا\nالدكتور شريح و ممتاز لكن مشكلتو تحسو كان يشرح علي منهج الي درسو في امريكا فصار شوية لخبطة\nحل معانا مسائل كتير\nبالنسبة للتصحيح سئ بس ما راح تفرق لانو الاختبار كومن", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1377809-che204", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdul-majeed-azad/157157/5", "user": "Abdullah7", "ts": 1402059449000, "tid": 157157, "pn": 5}}]}', 1402059449000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abo_fauzi-che204', 'stk-abo_fauzi', 'CHE 204', 'doc', '{"docs": [{"id": "stk-dr-f172454", "n": "Dr. Umer Zahid", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHE204 - TERM152\nترم 152 هو أول ترم للدكتور في الجامعة …\nالتحضير : كل كلاس ورقة تمر على الطلاب ومايحب التأخير.\nطريقة الشرح : يشرح من سلايدات وأحياناً يكتب على السبورة اذا كان فيه مسألة أو نقطة تحتاج شرح … بالنسبة لجودة الشرح وسط لا هي سيئة صراحة ولا هي ممتازة يعني ممكن تفهم معاه\nالكويزات : الكويزات كانت 4 كويزات كل كويز جزء كونسبت وجزء مسائل … بشكل عام لو انك مذاكر كويس حتشوف الكويزات سهلة لأنها غالباً تختبر فهمك وما فيها تعقيد ( ترم 152 كان فيه دكتورين يدرسوا الكورس والكويزات كانت كومن بينهم )\nالمياجر: ميدتريم متوسط الصعوبة\nالفاينلات : الفاينل في المادة ذي كان سهل بشكل غريب\nالقريد النهائي: B\nالصوت: واضح بشكل طيب\nإضافات : الدكتور أخلاقه جداً عاالية ومتفاهم ويضحك أحياناً مع الطلاب … متعاون في الأوفس أور ويرحب بيك بشكل كبير … بعد الميدتريم اذا حسيت انو درجتك نازلة نصيحة راجعه في المكتب :msn-wink:", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1462498-che204", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/umer-zahid/172454/4", "user": "Abo_Fauzi", "ts": 1479391218000, "tid": 172454, "pn": 4}}]}', 1479391218000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-yazeedgh-che204', 'stk-yazeedgh', 'CHE 204', 'doc', '{"docs": [{"id": "stk-dr-f172454", "n": "Dr. Umer Zahid", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Che 204 - 161\n\nالتحضير : ورقة تمر عالطلاب وبعض الاحيان يتاكد من الاسامي للي يحضرون لبعض\nوالميك اب كنت بعض الاحيان احضر بالسكشن الثاني ويسالني ليه ومع الوقت تعود\nطريقة الشرح : شرحه اشوفه جيد بس لازم تركز معه وما تغيب لان الدروس تتبع بعض\nالكويزات : جزء كتاب مغلق وعباره عن كونسبت يعطيك اول 10 دقايق سهله نوعا ما ولو تعرف احد الاترام اللي قبل يعطيك الاسئله لانها تتكرر وجزء كتاب مغلق وتكون مسالتين متوسطة الصعوبه\nالمياجر: ميد وكان متوسط مايل للسهوله والافرج 78 على ما اظن وكان 4 مسائل اظن\nالفاينلات : ساعتين ونص ومسائل كثير وصعبه\nالقريد النهائي: سي +\nالصوت: ممتاز\nإضافات : كنت تحت الافرج في الميد وجايب العيد بالكويزات واخذت قريت ما توقعته\n+ يهتم بالهوموركات وتاكد من صحتها لان تصحيحه شديد", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1467622-che204", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/umer-zahid/172454/5", "user": "yazeedgh", "ts": 1486249188000, "tid": 172454, "pn": 5}}]}', 1486249188000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-khdsa2022-che204', 'stk-khdsa2022', 'CHE 204', 'doc', '{"docs": [{"id": "stk-dr-f172454", "n": "Dr. Umer Zahid", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بنود التقييم - منقول عبر واتساب\n\nاسم المدرس : عمر زاهد\nالمادة : che 204\nالترم: 183\n\nالتحضير : كل يوم ورقة\nطريقة الشرح : ممتازه\nالكويزات : متوسطه\nالمياجر: متوسطة الى صعبه\nالفاينلات : متوسطة نفس مستوى الميجر الثاني\nالقريد النهائي: اعطيه A\nالصوت: واضح\nإضافات : الدكتور طيب و يمشي لكن لا تكلمه عن التصحيح او تطلب انه يعدل شي", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1513682-che204", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/umer-zahid/172454/6", "user": "Khdsa2022", "ts": 1565783847000, "tid": 172454, "pn": 6}}]}', 1565783847000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-neran-che204', 'stk-neran', 'CHE 204', 'doc', '{"docs": [{"id": "stk-dr-f172454", "n": "Dr. Umer Zahid", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHE 204 Term 183\nالتحضير : ورقة تمر على الطلاب ومايشدد على المتأخرين\nطريقة الشرح : شرحه للكونسبت متوسط لكن يشرح المسائل بشكل ممتاز جدا واغلب الكلاسات يكون حل مسائل\nالكويزات : كوزاته متوسطه الى صعبه\nالمياجر: الميجر الاول سهل والثاني كان صعب\nالفاينلات :الفاينل كان متوسط\nالقريد النهائي: B+\nالصوت: واضح\nإضافات :الدكتور طيب جدا وجبيب ومتساعد مع الطلاب. في التصحيح يعطيك حقك.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1519312-che204", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/umer-zahid/172454/7", "user": "neran", "ts": 1579792096000, "tid": 172454, "pn": 7}}]}', 1579792096000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdullah_mah-che204', 'stk-abdullah_mah', 'CHE 204', 'doc', '{"docs": [{"id": "stk-dr-f182606", "n": "Dr. Donghyun Kim", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "192\nCHE 204\n\nطريقة الشرح : سلايدات عن الكتاب يشرحها و يتناقش القوانين, بعد كذا يحل امثلة الكتاب\nشرحه كان جميل في البداية, بس بعدين صار كلاسه جدا ممل, خصوصا لمن انتقلنا لكلاسات الاون لاين لان طريقة الشرح تغيرت هناك, كان يسوي\nrecorded meeting يشرح لنا و يحل امثلة or online meeting عشان يجاوب على اسئلتنا.\n\nالكويزات : اخذنا اول كويز قبل الكورونا, كان نوعا ما سهل\nالكوز الثاني كان اون لاين لكن انلغى, لانه يقول في نسبة كبيرة من الطلاب غشوا فيه, انتهى الترم و احنا اخذنا كوز واحد بس, المشكلة الكوزات عليها 10%, راح تتحدد من كوز واحد بس!!! كل هذا بسبب الاوضاع الحالية.\n\nالمياجر: اختبرنا اول ميجر قبل الكورونا, كان صعب و غير منصف للأمانة, اول سؤال كتبه كيم و كان مثال من الكتاب لكنه ما شرحه لنا في الكلاس. الافرج كان 26/45\nالميجر الثاني كان اون لاين, (((( 20 )))) مسألة من الكتاب نحلها و نسلمها بعد 4 ايام, اعتقد ما يحتاج اقول الباقي, لكن اغلب درجات الطلاب كانت عالية.\n\nالفاينلات : مرة ثانية اون لاين, كان 5 مسائل الدكاترة كاتبينهم هذي المرة مش من كتاب, كانت مسائل صعبة الصراحة و الوقت ضيق, 24 ساعة متاحة فقط الين التسليم.\n\nالقريد النهائي: c+\n\nالصوت: واضح معا لهجة كوريا.\n\nإضافات : الدكتور صغير و جديد اول ترم له, يتاخر في التصحيح بشكل ملحوظ سواء للكوزات او الاختبارات, يعيبه انه تنقصه الخبرة, ما انصح فيه الا اذا كنت محتد.\n\nلا تنسوني من الدعاء (:", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1521805-che204", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/donghyun-kim/182606/2", "user": "Abdullah_MAH", "ts": 1588735657000, "tid": 182606, "pn": 2}}]}', 1588735657000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11325-che204', 'stk-user11325', 'CHE 204', 'doc', '{"docs": [{"id": "stk-dr-f182606", "n": "Dr. Donghyun Kim", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "201- che 204 (كورونا، اون لاين)\nالدكتور كيم ممتاز ويركز على حل المسائل، وكلاساته خفيفة مشكلته الوحيدة انه يعطي كويزات قليلة طيلة الترم تقريبا 2 بس ووزنهم 10٪ او 20٪ (لسه ماانتهى الترم والقسم بيعطي قرار نهائي عن التوزيع نهاية الترم) يعني قهر شوي\n\nالمهم الدكتور جديد ماله سنة او سنة ونص بالجامعة ماهو سيء مثل اللي ينقال عنه احيانا اقيمه 6/10.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1526919-che204", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/donghyun-kim/182606/3", "user": "user11325", "ts": 1607069487000, "tid": 182606, "pn": 3}}]}', 1607069487000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-unlucky-che204', 'stk-unlucky', 'CHE 204', 'doc', '{"docs": [{"id": "stk-dr-f182606", "n": "Dr. Donghyun Kim", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "201-Che204\n\nالتحضير : الدكتور من ناحية التحضير مرن جدًا يرسل أسئلة حلها وخش بعدها رابط الكلاس بالزوم ووضعك طيب\nطريقة الشرح : الدكتور جديد بالجامعة وشرحه متواضع، يحاول يوصل الفكرة ويجتهد . يرسل مقطع شرح بسيط ويخش سيده بالأسئلة وهذا شيء غلط .\nالكويزات : كويزين كل الترم وكل واحد عليه ١٠ بالمية + كلها نسخ لصق من السجستد\nالمياجر: كان الوضع ميد وكان صعب الافرج بالخمسين\nالفاينلات : الفاينل سهل\nالقريد النهائي: B+\nالصوت: أحد يقيم على الصوت!\nإضافات : الدكتور كلاساته الي قبل الاختبارات مفيدة ويلخص لك الماتيريال بأبسط صورة، يحب أسئلة الكونسبت+ يجيب لك سؤال من الميد أو الفاينل من شرحه الي بالكلاس بس يغير شويتين .\nتصحيح الدكتور كويس جدًا واذا شافك فاهم ممكن ما يخصم عليك واجد .\nالدكتور مايرد عالايميل واذا رد ممكن يجلس شهر فلو تبي شيء ضروري مالك الا تكلمه تيمز ولا بوسط الكلاس", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1529225-che204", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/donghyun-kim/182606/5", "user": "Unlucky", "ts": 1616760543000, "tid": 182606, "pn": 5}}]}', 1616760543000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-guest-che204', 'stk-guest', 'CHE 204', 'doc', '{"docs": [{"id": "stk-dr-f182607", "n": "Dr. Usama Ahmed", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Che 204 - Term 192\n\nالتحضير : الدكتور كان يوزع ورقة في الكلاس والميك اب كان مسموح ثلاث مرات فقط خلال الترم.\n\nطريقة الشرح : الدكتور كان يشرح من السلايدات ويحل مسائل كثير. شرحه للمسائل كان وسط لكنه أوضح من شرحه للكونسبت.\n\nالكويزات : اختبرنا كويزين الأول على تشابتر 2 و 3 والثاني على تشابتر 5 على ما أتذكر. مستوى الكويزات كان أعلى من الهوموورك لكن معقول. التصحيح في الكويزات والواحب كان من القريدر وكان جيد صراحة.\n\nالمياجر: كومن وميجر1 كان صعب نسبيا.\nالفاينلات : كومن\nالقريد النهائي: من C+ إلى B\nالصوت: مع الأسف الآكسنت سيء لازم تركز عشان تفهم.\nإضافات : الدكتور في التعامل حسب تجربتي ما كان متعاون مرة. كان ناوي يخلي النجاح من 70 في الترم مع ان الآفرج في ميجر 1 كان تحت ال 60. لكن الحمدلله في النهاية صار النجاح في الترم من 60 بعد التواصل مع التشيرمان. وبشكل عام ما كان يوضح كثير من الأمور المهمة مثل عدد الأسئلة في المياجر والفاينل والوقت إلخ.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1522170-che204", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/usama-ahmed/182607/2", "user": "Guest", "ts": 1589922723000, "tid": 182607, "pn": 2}}]}', 1589922723000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
